		"helm charts/api/templates/cm.yaml":               "helm",
	} {
		f, ok := got[key]
		if !ok {
			t.Errorf("no finding %q among %v", key, keys(got))
			continue
		}
		if f.IaCType != dialect || f.Line != 0 {
			t.Errorf("%s: type %q line %d, want %q and no line", key, f.IaCType, f.Line, dialect)
		}
	}
	if len(result.Errors) != 0 {
		t.Errorf("errors = %v, want none", result.Errors)
	}
}

// A chart that does not render is a finding, not a failed scan — helm lint
// only warns about a missing dependency, and it is the render that fails.
func TestAChartThatDoesNotRenderIsAFinding(t *testing.T) {
	isolateHome(t)
	repo := renderRepo(t)
	renderRunner(t, stageReply{err: &exitError{Code: 1,
		Stderr: "Error: found in Chart.yaml, but missing in charts/ directory: redis\nmore"}})

	result, _ := newScannerWithDeps(k8sSchema(), renderingDeps()).
		Scan(t.Context(), repo, TargetDirectory)

	var render *Finding
	for i, f := range result.Findings {
		if f.ID == K8sRenderID {
			render = &result.Findings[i]
		}
	}
	if render == nil {
		t.Fatalf("no render finding among %+v", result.Findings)
	}
	if render.File != "charts/api/Chart.yaml" || !strings.HasSuffix(render.Title, "missing in charts/ directory: redis") {
		t.Errorf("render finding = %q in %q", render.Title, render.File)
	}
	if len(result.Errors) != 0 {
		t.Errorf("errors = %v, want none: the scan itself did not fail", result.Errors)
	}
}

// Without helm or kustomize, nothing about charts and overlays is claimed:
// they are listed as not rendered, and no tool is reported missing — they are
// optional.
func TestWithoutRenderersChartsAndOverlaysAreNotRendered(t *testing.T) {
	isolateHome(t)
	repo := renderRepo(t)
	r := &scriptedRunner{reply: func(tc toolCmd) ([]byte, error) {
		t.Errorf("ran %s with no renderer and no plain manifest", tc)
		return nil, nil
	}}
	useRunner(t, r)
	deps := binaries(ToolTrivy, ToolGitleaks, ToolKubeconform)

	result, _ := newScannerWithDeps(k8sSchema(), deps).Scan(t.Context(), repo, TargetDirectory)

	if want := []string{"charts/api", "k8s/overlays/prod"}; !reflect.DeepEqual(result.K8sUnrendered, want) {
		t.Errorf("K8sUnrendered = %v, want %v", result.K8sUnrendered, want)
	}
	if len(result.Errors) != 0 {
		t.Errorf("errors = %v, want none", result.Errors)
	}
}

func keys(m map[string]Finding) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}
package scan

import (
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/engine"
	"github.com/anthnel/devdesk/internal/netproxy"
)

// DEVDESK-583, step 3: every `<engine> run --rm` goes through containerRun.cmd,
// which adds `-e NAME` for each proxy variable to forward, right before the
// image, and puts the values in the child's environment, never in argv. The
// argv produced with no proxy is frozen by container_builders_test.go
// (TestContainerBuildersWithoutProxyAreUnchanged); this file does not repeat it.

const (
	fwdHTTPValue  = "REDACTED"
	fwdHTTPSValue = "REDACTED"
	fwdNoValue    = "internal.example.net,.corp.example.net"
)

// fwdLeaks is everything that must never appear in an argv or in a displayed
// command: the raw values and the pieces a credential or a host is made of.
var fwdLeaks = []string{
	fwdHTTPValue, fwdHTTPSValue, fwdNoValue,
	"s3cr3tREDACTED", "hunter2REDACTED", "alice-user", "bob-user",
	"proxy.example.com", "3128", "internal.example.net", "corp.example.net",
}

// fullProxy is the three pairs, each given in its upper case name only.
var fullProxy = map[string]string{
	"HTTP_PROXY":  fwdHTTPValue,
	"HTTPS_PROXY": fwdHTTPSValue,
	"NO_PROXY":    fwdNoValue,
}

// forwardOf builds a Forward from the variables a process would have.
func forwardOf(vars map[string]string) netproxy.Forward {
	return netproxy.ForwardFromLookup(func(name string) (string, bool) {
		v, ok := vars[name]
		return v, ok
	})
}

// useProxy swaps the seam for one test and restores it afterwards.
func useProxy(t *testing.T, fwd netproxy.Forward) {
	t.Helper()
	previous := proxyForward
	proxyForward = func() netproxy.Forward { return fwd }
	t.Cleanup(func() { proxyForward = previous })
}

// forEachEngine runs fn once per engine the scanners can use.
func forEachEngine(t *testing.T, fn func(t *testing.T, binary string)) {
	t.Helper()
	for _, name := range []string{engine.Docker, engine.Podman} {
		t.Run(name, func(t *testing.T) {
			useEngine(t, engine.ShapeFor(name))
			fn(t, engine.Current().Binary)
		})
	}
}

// pairsOf lists "-e NAME" for each name.
func pairsOf(names []string) []string {
	var out []string
	for _, n := range names {
		out = append(out, "-e", n)
	}
	return out
}

// containerImages are the images the cases of containerBuilders run.
var containerImages = []string{
	"aquasec/trivy", "zricethezav/gitleaks", DefaultCosignImage,
	"registry.example.com/tools/img:1", "getplumber/plumber",
	"ghcr.io/yannh/kubeconform", "alpine/helm", "registry.k8s.io/kustomize/kustomize:v5.8.1",
}

// withNamesBeforeImage returns args with the -e pairs of names inserted right
// before the image, which is where containerRun.cmd puts them.
func withNamesBeforeImage(t *testing.T, args []string, names []string) []string {
	t.Helper()
	at := slices.IndexFunc(args, func(a string) bool { return slices.Contains(containerImages, a) })
	if at < 0 {
		t.Fatalf("no known image in %q", args)
	}
	return slices.Concat(args[:at], pairsOf(names), args[at:])
}

// checkNoLeak fails when s contains any proxy value or piece of one.
func checkNoLeak(t *testing.T, what, s string) {
	t.Helper()
	for _, leak := range fwdLeaks {
		if strings.Contains(s, leak) {
			t.Errorf("%s contains %q: %s", what, leak, s)
		}
	}
}

// checkProxyEnv fails unless env holds each variable of want exactly once with
// its value, and none of the other proxy variables.
func checkProxyEnv(t *testing.T, env []string, want map[string]string) {
	t.Helper()
	for _, name := range netproxy.ForwardedVariables {
		var found []string
		for _, kv := range env {
			if strings.HasPrefix(kv, name+"=") {
				found = append(found, kv)
			}
		}
		value, expected := want[name]
		switch {
		case !expected && len(found) > 0:
			t.Errorf("Env carries %q although %s is not forwarded", found, name)
		case expected && !slices.Equal(found, []string{name + "=" + value}):
			t.Errorf("Env entries for %s = %q, want exactly %q", name, found, name+"="+value)
		}
	}
}

// bothCasings gives each upper case name of vars its lower case twin.
func bothCasings(vars map[string]string) map[string]string {
	out := map[string]string{}
	for name, value := range vars {
		out[name] = value
		out[strings.ToLower(name)] = value
	}
	return out
}

func TestContainerRunWithoutProxyAddsNothing(t *testing.T) {
	useProxy(t, netproxy.Forward{})
	forEachEngine(t, func(t *testing.T, binary string) {
		got := containerRun{
			Flags: []string{"-v", "/repo:/scan:ro", "-w", "/scan"},
			Image: "img:1",
			Argv:  []string{"tool", "--flag"},
			Stdin: []byte("in"),
		}.cmd()
		want := []string{"run", "--rm", "-v", "/repo:/scan:ro", "-w", "/scan", "img:1", "tool", "--flag"}
		if got.Name != binary || !slices.Equal(got.Args, want) {
			t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
		}
		if got.Env != nil {
			t.Errorf("Env = %q, want nil", got.Env)
		}
		if string(got.Stdin) != "in" {
			t.Errorf("Stdin = %q, want it carried", got.Stdin)
		}
	})
}

func TestContainerRunWithoutProxyKeepsExtraEnvironment(t *testing.T) {
	useProxy(t, netproxy.Forward{})
	forEachEngine(t, func(t *testing.T, _ string) {
		got := containerRun{
			Flags: []string{"-e", "TOKEN"},
			Image: "img:1",
			Env:   []string{"TOKEN=t0k3n"},
		}.cmd()
		if want := []string{"run", "--rm", "-e", "TOKEN", "img:1"}; !slices.Equal(got.Args, want) {
			t.Errorf("Args = %q, want %q", got.Args, want)
		}
		if want := slices.Concat(os.Environ(), []string{"TOKEN=t0k3n"}); !slices.Equal(got.Env, want) {
			t.Errorf("Env = %q, want os.Environ() plus the credential %q", got.Env, want)
		}
	})
}

func TestContainerRunForwardsTheProxyByName(t *testing.T) {
	fwd := forwardOf(map[string]string{"HTTPS_PROXY": "REDACTED"})
	useProxy(t, fwd)
	// A stale value in this process must lose to the forwarded one.
	t.Setenv("HTTPS_PROXY", "http://stale.example.org:1")
	forEachEngine(t, func(t *testing.T, binary string) {
		got := containerRun{
			Flags: []string{"-v", "/repo:/scan:ro", "-e", "TOKEN"},
			Image: "img:1",
			Argv:  []string{"tool"},
			Env:   []string{"TOKEN=t0k3n"},
		}.cmd()
		want := []string{"run", "--rm", "-v", "/repo:/scan:ro", "-e", "TOKEN",
			"-e", "HTTPS_PROXY", "-e", "https_proxy", "img:1", "tool"}
		if got.Name != binary || !slices.Equal(got.Args, want) {
			t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
		}
		for _, a := range got.Args {
			if strings.Contains(a, "REDACTED") || strings.Contains(a, "p:3128") {
				t.Errorf("argv element %q carries the proxy", a)
			}
		}
		if s := got.String(); strings.Contains(s, "REDACTED") || strings.Contains(s, "p:3128") {
			t.Errorf("String() carries the proxy: %s", s)
		}
		checkProxyEnv(t, got.Env, map[string]string{
			"HTTPS_PROXY": "REDACTED", "https_proxy": "REDACTED",
		})
		// The credentials come after the proxy pairs, and the rest of the
		// environment is kept.
		if want := slices.Concat(fwd.Environ(os.Environ()), []string{"TOKEN=t0k3n"}); !slices.Equal(got.Env, want) {
			t.Errorf("Env =\n  %q\nwant\n  %q", got.Env, want)
		}
	})
}

// TestEveryContainerBuilderForwardsTheProxy runs every launcher of
// containerBuilders with the three pairs set: the six -e NAME sit right before
// the image, nothing else moves, no value reaches argv or the displayed
// command, and the child's environment carries them.
func TestEveryContainerBuilderForwardsTheProxy(t *testing.T) {
	fwd := forwardOf(fullProxy)
	useProxy(t, fwd)
	forEachEngine(t, func(t *testing.T, _ string) {
		for _, tc := range containerBuilders() {
			t.Run(tc.name, func(t *testing.T) {
				useProxy(t, netproxy.Forward{})
				plain := tc.build()
				useProxy(t, fwd)
				got := tc.build()

				if want := withNamesBeforeImage(t, plain.Args, netproxy.ForwardedVariables); !slices.Equal(got.Args, want) {
					t.Errorf("Args =\n  %q\nwant\n  %q", got.Args, want)
				}
				if got.Name != plain.Name || got.Dir != plain.Dir || string(got.Stdin) != string(plain.Stdin) {
					t.Errorf("Name, Dir or Stdin changed: %q %q %q, was %q %q %q",
						got.Name, got.Dir, got.Stdin, plain.Name, plain.Dir, plain.Stdin)
				}
				for _, a := range got.Args {
					checkNoLeak(t, "argv element", a)
				}
				checkNoLeak(t, "String()", got.String())

				checkProxyEnv(t, got.Env, bothCasings(fullProxy))
				if want := slices.Concat(fwd.Environ(os.Environ()), tc.env); !slices.Equal(got.Env, want) {
					t.Errorf("Env is not the forwarded environment plus the credentials:\n  %q\nwant\n  %q", got.Env, want)
				}
			})
		}
	})
}

// TestContainerBuildersProxyForwardsOnlyTheNamesSet: a pair that is not set is
// not passed, and a pair set in one casing is passed in both.
func TestContainerBuildersProxyForwardsOnlyTheNamesSet(t *testing.T) {
	noProxyEnvironment(t) // the case where nothing is forwarded keeps os.Environ() as is
	cases := []struct {
		name string
		vars map[string]string
		want map[string]string // what the child's environment must hold
	}{
		{"NO_PROXY alone", map[string]string{"NO_PROXY": fwdNoValue},
			map[string]string{"NO_PROXY": fwdNoValue, "no_proxy": fwdNoValue}},
		{"HTTP_PROXY alone", map[string]string{"HTTP_PROXY": fwdHTTPValue},
			map[string]string{"HTTP_PROXY": fwdHTTPValue, "http_proxy": fwdHTTPValue}},
		{"lower case https_proxy alone", map[string]string{"https_proxy": fwdHTTPSValue},
			map[string]string{"HTTPS_PROXY": fwdHTTPSValue, "https_proxy": fwdHTTPSValue}},
		{"HTTPS_PROXY and NO_PROXY", map[string]string{"HTTPS_PROXY": fwdHTTPSValue, "NO_PROXY": fwdNoValue},
			map[string]string{"HTTPS_PROXY": fwdHTTPSValue, "https_proxy": fwdHTTPSValue,
				"NO_PROXY": fwdNoValue, "no_proxy": fwdNoValue}},
		{"ALL_PROXY is not read", map[string]string{"ALL_PROXY": fwdHTTPValue, "FTP_PROXY": fwdHTTPValue}, nil},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			fwd := forwardOf(c.vars)
			forEachEngine(t, func(t *testing.T, _ string) {
				for _, tc := range containerBuilders() {
					t.Run(tc.name, func(t *testing.T) {
						useProxy(t, netproxy.Forward{})
						plain := tc.build()
						useProxy(t, fwd)
						got := tc.build()

						if want := withNamesBeforeImage(t, plain.Args, fwd.Names()); !slices.Equal(got.Args, want) {
							t.Errorf("Args =\n  %q\nwant\n  %q", got.Args, want)
						}
						for _, a := range got.Args {
							checkNoLeak(t, "argv element", a)
						}
						checkProxyEnv(t, got.Env, c.want)
					})
				}
			})
		})
	}
}

// TestCosignProxyKeepsRegistryCredentials: the existing -e COSIGN_REGISTRY_*
// stay once, in front of the proxy names, with their values after the
// forwarded variables in Env.
func TestCosignProxyKeepsRegistryCredentials(t *testing.T) {
	fwd := forwardOf(fullProxy)
	useProxy(t, fwd)
	forEachEngine(t, func(t *testing.T, _ string) {
		checked := 0
		for _, tc := range containerBuilders() {
			if !strings.HasPrefix(tc.name, "cosign") || len(tc.env) == 0 {
				continue
			}
			checked++
			t.Run(tc.name, func(t *testing.T) {
				got := tc.build()
				first := slices.Index(got.Args, "HTTP_PROXY")
				for _, name := range []string{cosignUserEnv, cosignPasswordEnv} {
					if n := strings.Count(strings.Join(got.Args, " "), name); n != 1 {
						t.Errorf("%s appears %d times in argv, want once: %q", name, n, got.Args)
					}
					at := slices.Index(got.Args, name)
					if at < 0 || first < 0 || at > first {
						t.Errorf("%s at %d must come before the proxy names (at %d): %q", name, at, first, got.Args)
					}
					if at > 0 && got.Args[at-1] != "-e" {
						t.Errorf("%s is not passed as -e NAME: %q", name, got.Args)
					}
				}
				for _, kv := range tc.env {
					if !slices.Contains(got.Env, kv) {
						t.Errorf("Env lost %s", strings.SplitN(kv, "=", 2)[0])
					}
				}
				if tail := got.Env[len(got.Env)-len(tc.env):]; !slices.Equal(tail, tc.env) {
					t.Errorf("credentials must come after the proxy variables: %q", got.Env)
				}
			})
		}
		if checked == 0 {
			t.Fatal("no cosign case with credentials in containerBuilders")
		}
	})
}

// TestGitleaksCommandProxyShowsNamesNotValues: the command the UI shows is
// replayable in the same shell, so it names the variables and carries none of
// their values.
func TestGitleaksCommandProxyShowsNamesNotValues(t *testing.T) {
	useProxy(t, forwardOf(fullProxy))
	forEachEngine(t, func(t *testing.T, _ string) {
		shown := GetGitleaksCommand("/repo", ToolSpec{Source: ToolSourceContainer}, false, "")
		for _, name := range netproxy.ForwardedVariables {
			if !strings.Contains(shown, " -e "+name+" ") {
				t.Errorf("command does not name %s: %s", name, shown)
			}
		}
		checkNoLeak(t, "the displayed command", shown)
	})
}

// TestContainerVersionCmdProxy covers the one launcher that was not a toolCmd.
func TestContainerVersionCmdProxy(t *testing.T) {
	t.Run("no proxy", func(t *testing.T) {
		useProxy(t, netproxy.Forward{})
		forEachEngine(t, func(t *testing.T, binary string) {
			got := containerVersionCmd("aquasec/trivy", "--version")
			if want := []string{"run", "--rm", "aquasec/trivy", "--version"}; got.Name != binary || !slices.Equal(got.Args, want) {
				t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
			}
			if got.Env != nil {
				t.Errorf("Env = %q, want nil", got.Env)
			}
		})
	})
	t.Run("proxy", func(t *testing.T) {
		fwd := forwardOf(fullProxy)
		useProxy(t, fwd)
		forEachEngine(t, func(t *testing.T, binary string) {
			got := containerVersionCmd("aquasec/trivy", "--version")
			want := slices.Concat([]string{"run", "--rm"}, pairsOf(netproxy.ForwardedVariables), []string{"aquasec/trivy", "--version"})
			if got.Name != binary || !slices.Equal(got.Args, want) {
				t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
			}
			for _, a := range got.Args {
				checkNoLeak(t, "argv element", a)
			}
			checkNoLeak(t, "String()", got.String())
			checkProxyEnv(t, got.Env, bothCasings(fullProxy))
		})
	})
}

// TestContainerToolVersionProxyEnvironment runs containerToolVersion through a
// fake engine: the proxy names are in its argv, the values only in the
// environment it was started with.
func TestContainerToolVersionProxyEnvironment(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("the fake engine is a shell script")
	}
	useProxy(t, forwardOf(fullProxy))
	script := filepath.Join(t.TempDir(), "docker")
	body := "#!/bin/sh\nfor a in \"$@\"; do printf '%s\\n' \"$a\"; done\n" +
		"printf 'env:HTTP_PROXY=%s\\n' \"$HTTP_PROXY\"\n" +
		"printf 'env:https_proxy=%s\\n' \"$https_proxy\"\n" +
		"printf 'env:no_proxy=%s\\n' \"$no_proxy\"\n"
	if err := os.WriteFile(script, []byte(body), 0o755); err != nil { //nolint:gosec // a test script must be executable
		t.Fatal(err)
	}
	shape := engine.ShapeFor(engine.Docker)
	shape.Binary = script
	useEngine(t, shape)

	got := containerToolVersion("aquasec/trivy", "--version")
	want := "docker:run\n--rm\n" +
		"-e\nHTTP_PROXY\n-e\nhttp_proxy\n-e\nHTTPS_PROXY\n-e\nhttps_proxy\n-e\nNO_PROXY\n-e\nno_proxy\n" +
		"aquasec/trivy\n--version\n" +
		"env:HTTP_PROXY=" + fwdHTTPValue + "\n" +
		"env:https_proxy=" + fwdHTTPSValue + "\n" +
		"env:no_proxy=" + fwdNoValue + "\n"
	if got != want {
		t.Errorf("containerToolVersion =\n%q\nwant\n%q", got, want)
	}
}

package config

import "slices"

// The scanners and the categories they serve, as the configuration names them.
//
// The table that says which tool serves which category, what each one needs and
// which are ticked by default lives in internal/scan (toolbox.go): it is the one
// source of truth. This file only declares the identifiers the YAML is written
// with, because the configuration cannot import the package that reads it —
// scan imports config, not the other way round. A test in scan checks that the
// two agree.

// Tool identifiers, as they appear under `scan.tools` and in a category's
// `tools` list.
const (
	ToolTrivy       = "trivy"
	ToolGitleaks    = "gitleaks"
	ToolPlumber     = "plumber"
	ToolKubeconform = "kubeconform"
	ToolHelm        = "helm"
	ToolKustomize   = "kustomize"
	// ToolCosign verifies image signatures (§3.82). It serves no category: it
	// runs before a pull as much as during a scan, and scan.image_verification
	// is its one switch.
	ToolCosign = "cosign"
)

// ToolIDs lists every scanner, in the order the tables use.
func ToolIDs() []string {
	return []string{ToolTrivy, ToolGitleaks, ToolPlumber, ToolKubeconform, ToolHelm, ToolKustomize, ToolCosign}
}

// Category identifiers, as they appear under `scan.categories`.
const (
	CategoryVuln      = "vuln"
	CategorySecret    = "REDACTED"
	CategoryMisconfig = "misconfig"
	CategoryLicense   = "license"
	CategoryCI        = "ci"
)

// CategoryIDs lists every category, in the order the tables use.
func CategoryIDs() []string {
	return []string{CategoryVuln, CategorySecret, CategoryMisconfig, CategoryLicense, CategoryCI}
}

// ToolConfig is what every scanner is configured with: where it runs from, and
// what to run.
type ToolConfig struct {
	Source string `yaml:"source"`           // auto | binary | image
	Binary string `yaml:"binary"`           // custom executable; empty resolves the name on PATH
	Image  string `yaml:"image"`            // OCI image; empty is the tool's default
	Config string `yaml:"config,omitempty"` // rules file, for the tools that read one
	// Args are extra arguments, placed after the tool's subcommand and before
	// DevDesk's own and the target. The flags DevDesk sets itself are refused
	// in the configuration view (scan.Tool.ReservedArgs).
	Args []string `yaml:"args,omitempty"`
}

// TrivyConfig adds what only Trivy has: the client-server mode and its two
// result filters.
type TrivyConfig struct {
	ToolConfig `yaml:",inline"`
	Server     TrivyServerConfig `yaml:"server"`
	// IgnoreUnfixed only shows vulnerabilities that have a fix.
	IgnoreUnfixed bool `yaml:"ignore_unfixed"`
	// IgnoreEOL drops end-of-life package vulnerabilities
	// (--ignore-status end_of_life).
	IgnoreEOL bool `yaml:"ignore_eol"`
}

// TrivyServerConfig is Trivy's client-server mode. The address is kept while
// the mode is off, so switching it back on does not lose what was typed — but a
// scan must not see it until Enabled says the mode is wanted.
type TrivyServerConfig struct {
	Enabled bool   `yaml:"enabled"`
	URL     string `yaml:"url"`
}

// GitleaksConfig adds whether git history is searched (omit --no-git).
type GitleaksConfig struct {
	ToolConfig `yaml:",inline"`
	History    bool `yaml:"history"`
}

// KubeconformConfig adds the release manifests are validated against, as
// kubeconform takes it: a full x.y.z, or "master". It decides whether an
// apiVersion counts as removed. Empty is DefaultKubernetesVersion.
type KubeconformConfig struct {
	ToolConfig        `yaml:",inline"`
	KubernetesVersion string `yaml:"kubernetes_version"`
}

// ScanTools is every scanner's settings, one block per tool.
type ScanTools struct {
	Trivy       TrivyConfig       `yaml:"trivy"`
	Gitleaks    GitleaksConfig    `yaml:"gitleaks"`
	Plumber     ToolConfig        `yaml:"plumber"`
	Kubeconform KubeconformConfig `yaml:"kubeconform"`
	Helm        ToolConfig        `yaml:"helm"`
	Kustomize   ToolConfig        `yaml:"kustomize"`
	Cosign      ToolConfig        `yaml:"cosign"`
}

// Tool returns the settings every scanner shares, by identifier — what lets
// defaults, path expansion and detection loop over the tools instead of
// repeating a block per tool. Nil for an unknown identifier.
func (t *ScanTools) Tool(id string) *ToolConfig {
	switch id {
	case ToolTrivy:
		return &t.Trivy.ToolConfig
	case ToolGitleaks:
		return &t.Gitleaks.ToolConfig
	case ToolPlumber:
		return &t.Plumber
	case ToolKubeconform:
		return &t.Kubeconform.ToolConfig
	case ToolHelm:
		return &t.Helm
	case ToolKustomize:
		return &t.Kustomize
	case ToolCosign:
		return &t.Cosign
	}
	return nil
}

// CategoryConfig is one category: whether it runs, and which of its tools run
// it. A category that is off keeps its list, the way the Trivy server keeps its
// address while the mode is off.
type CategoryConfig struct {
	Enabled bool     `yaml:"enabled"`
	Tools   []string `yaml:"tools"`
}

// Has reports whether a tool is ticked in this category, whether or not the
// category itself is on.
func (c CategoryConfig) Has(tool string) bool {
	return slices.Contains(c.Tools, tool)
}

// With returns the category with a tool ticked or unticked. The list is always
// a new slice: a Config is copied by value between views, and an in-place edit
// would reach into every copy that shares the backing array.
func (c CategoryConfig) With(tool string, on bool) CategoryConfig {
	tools := slices.DeleteFunc(slices.Clone(c.Tools), func(t string) bool { return t == tool })
	if on {
		tools = append(tools, tool)
	}
	c.Tools = tools
	return c
}

// ScanCategories is what a scan looks for.
type ScanCategories struct {
	Vuln      CategoryConfig `yaml:"vuln"`
	Secret    CategoryConfig `yaml:"secret"`
	Misconfig CategoryConfig `yaml:"misconfig"`
	License   CategoryConfig `yaml:"license"`
	CI        CategoryConfig `yaml:"ci"`
}

// Category returns one category by identifier. Nil for an unknown identifier.
func (c *ScanCategories) Category(id string) *CategoryConfig {
	switch id {
	case CategoryVuln:
		return &c.Vuln
	case CategorySecret:
		return &c.Secret
	case CategoryMisconfig:
		return &c.Misconfig
	case CategoryLicense:
		return &c.License
	case CategoryCI:
		return &c.CI
	}
	return nil
}

// isZero is a `categories` block the file does not carry: nothing on and no
// tool ticked anywhere. A block written by DevDesk always ticks tools, since
// the defaults do and a category that is off keeps its list, so an all-off one
// is still an answer. An empty list counts as absent: a zero Config saves
// `tools: []`, which is not a choice anyone made.
func (c ScanCategories) isZero() bool {
	for _, id := range CategoryIDs() {
		cat := c.Category(id)
		if cat.Enabled || len(cat.Tools) > 0 {
			return false
		}
	}
	return true
}

// DefaultScanCategories is what a new context scans for: vulnerabilities and
// secrets, with each category's default tools ticked. The defaults must match
// the table in internal/scan, which a test there checks.
func DefaultScanCategories() ScanCategories {
	return ScanCategories{
		Vuln:      CategoryConfig{Enabled: true, Tools: []string{ToolTrivy}},
		Secret:    CategoryConfig{Enabled: true, Tools: []string{ToolTrivy, ToolGitleaks}},
		Misconfig: CategoryConfig{Tools: []string{ToolTrivy}},
		License:   CategoryConfig{Tools: []string{ToolTrivy}},
		CI:        CategoryConfig{Tools: []string{ToolPlumber}},
	}
}
